import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { AuthService } from '../services/auth/auth.service';
import { UserState } from '../../modules/users/enum/user-state.enum';
import { CAMBIO_PASSWORD_URL } from './public.guard';

export const authGuard: CanActivateFn = ( route, state ) => {
  const authService = inject(AuthService);
  const router = inject(Router);
  const user = authService.currentUser();

  if(authService.isAuthenticated() && user?.state === UserState.active ){
    // Con la contraseña que asignó un administrador, primero debe cambiarla
    if (authService.debeCambiarPassword()) {
      router.navigate([CAMBIO_PASSWORD_URL]);
      return false;
    }
    return true;
  }

  if (user && user.state !== UserState.active) {
    console.warn('Sesión bloqueada: El usuario ha sido inhabilitado.');
    authService.logout();
  } else {
    router.navigate(['/auth/login']);
  }

  return false;
};

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { AuthService } from '../services/auth/auth.service';
import { UserRoleType } from '../enums/user-role-type.enum';

export const roleGuard: CanActivateFn = ( route, state ) => {
  const authService = inject(AuthService);
  const router = inject(Router);

  const allowedRoles = route.data['roles'] as UserRoleType[];

  if(authService.isAuthenticated() && authService.hasAnyRole(allowedRoles)){
    return true;
  }

  console.warn('Acceso denegado: No tienes los roles necesarios.');
  router.navigate(['/notifications']);
  return false;
};

import { TestBed, fakeAsync, tick, flushMicrotasks } from '@angular/core/testing';
import { Injector, signal, WritableSignal, ApplicationRef } from '@angular/core';

if (typeof globalThis.structuredClone === 'undefined') {
  globalThis.structuredClone = (val: unknown) => JSON.parse(JSON.stringify(val));
}

import { resolveEntityForGuard } from '../resolve-entity-for-guard.helper';

describe('Integración [Core]: Barrera Asíncrona de Hidratación en Guards', () => {
  let injector: Injector;
  let isHydratedSignal: WritableSignal<boolean>;
  let dbMock: any[];
  let appRef: ApplicationRef;

  beforeAll(() => {
    jest.spyOn(console, 'error').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
  });

  afterAll(() => {
    jest.restoreAllMocks();
  });

  beforeEach(() => {
    TestBed.configureTestingModule({});
    injector = TestBed.inject(Injector);
    appRef = TestBed.inject(ApplicationRef);

    isHydratedSignal = signal(false);
    dbMock = [];
  });

  it('debe pausar la ejecución de la ruta hasta que IndexedDB (isHydrated) termine de cargar', fakeAsync(() => {
    dbMock = [{ id: 'documento-secreto-123', autor: 'Simón' }];
    let resolvedEntity: any = undefined;
    let hasResolved = false;

    resolveEntityForGuard(
      isHydratedSignal,
      () => dbMock,
      (item: any) => item.id === 'documento-secreto-123',
      injector
    ).then(result => {
      resolvedEntity = result;
      hasResolved = true;
    });
    tick(5000);
    expect(hasResolved).toBe(false);
    expect(resolvedEntity).toBeUndefined();
    isHydratedSignal.set(true);
    appRef.tick();
    flushMicrotasks();
    expect(hasResolved).toBe(true);
    expect(resolvedEntity.autor).toBe('Simón');
  }));

  it('debe resolver instantáneamente si el storage ya estaba hidratado desde antes', fakeAsync(() => {
    dbMock = [{ id: 'doc-publico', autor: 'Admin' }];
    isHydratedSignal.set(true);
    let hasResolved = false;

    resolveEntityForGuard(
      isHydratedSignal,
      () => dbMock,
      (item: any) => item.id === 'doc-publico',
      injector
    ).then(() => {
      hasResolved = true;
    });
    appRef.tick();
    flushMicrotasks();
    expect(hasResolved).toBe(true);
  }));
});

import { TestBed } from '@angular/core/testing';
import {
  Router,
  NavigationEnd,
  Event as RouterEvent,
  ActivatedRouteSnapshot,
  RouterStateSnapshot,
  NavigationStart
} from '@angular/router';
import { Title } from '@angular/platform-browser';
import { Observable, Subject } from 'rxjs';
import { BreadcrumbService } from './breadcrumb.service';
import { buildBreadcrumbTrail } from './helpers/breadcrumb-builder.helper';
import { BreadcrumbItem } from '../../interfaces/breadcrumb-item.interface';

jest.mock('./helpers/breadcrumb-builder.helper', () => ({
  buildBreadcrumbTrail: jest.fn()
}));

const createMockRouteSnapshot = (): ActivatedRouteSnapshot => {
  const dummyParamMap = { has: () => false, get: () => null, getAll: () => [], keys: [] };
  const snapshot: ActivatedRouteSnapshot = {
    url: [],
    params: {},
    queryParams: {},
    fragment: null,
    data: {},
    outlet: 'primary',
    component: null,
    routeConfig: null,
    get root() { return snapshot; },
    parent: null,
    firstChild: null,
    children: [],
    pathFromRoot: [],
    paramMap: dummyParamMap,
    queryParamMap: dummyParamMap,
    title: ''
  };
  return snapshot;
};

interface MockTitleService {
  setTitle: jest.Mock<void, [string]>;
  getTitle: jest.Mock<string, []>;
}

type MockRouter = Pick<Router, 'events' | 'url'> & { routerState: { snapshot: RouterStateSnapshot } };

describe('BreadcrumbService', () => {
  let service: BreadcrumbService;
  let mockTitleService: MockTitleService;
  let mockRouter: MockRouter;
  let routerEventsSubject: Subject<RouterEvent>;
  let mockSnapshot: RouterStateSnapshot;
  const buildBreadcrumbTrailMock = jest.mocked(buildBreadcrumbTrail);

  beforeEach(() => {
    jest.spyOn(console, 'error').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});

    routerEventsSubject = new Subject<RouterEvent>();

    mockSnapshot = {
      root: createMockRouteSnapshot(),
      url: '/ruta-actual'
    };

    mockRouter = {
      events: routerEventsSubject.asObservable(),
      url: '/ruta-actual',
      routerState: { snapshot: mockSnapshot }
    };

    mockTitleService = {
      setTitle: jest.fn(),
      getTitle: jest.fn()
    };

    buildBreadcrumbTrailMock.mockReturnValue([
      { label: 'Ruta 1', url: '/ruta-1' }
    ]);

    TestBed.configureTestingModule({
      providers: [
        BreadcrumbService,
        { provide: Router, useValue: mockRouter },
        { provide: Title, useValue: mockTitleService }
      ]
    });

    service = TestBed.inject(BreadcrumbService);
  });

  afterEach(() => {
    jest.clearAllMocks();
    jest.restoreAllMocks();
  });

  describe('Inicialización y Signals Computed', () => {
    it('debería crearse correctamente', () => {
      expect(service).toBeTruthy();
    });

    it('debería generar los breadcrumbs iniciales con "Inicio" y el resultado del helper', () => {
      const breadcrumbs = service.breadcrumbs();
      expect(breadcrumbs).toEqual([
        { label: 'Inicio', url: '/' },
        { label: 'Ruta 1', url: '/ruta-1' }
      ]);
      expect(buildBreadcrumbTrailMock).toHaveBeenCalledWith(mockSnapshot.root);
    });

    it('debería añadir el dynamicLabel al final de los breadcrumbs si está presente', () => {
      service.setDynamicBreadcrumb('Detalle Extra');
      const breadcrumbs = service.breadcrumbs();
      expect(breadcrumbs).toEqual([
        { label: 'Inicio', url: '/' },
        { label: 'Ruta 1', url: '/ruta-1' },
        { label: 'Detalle Extra', url: '/ruta-actual' }
      ]);
    });
  });

  describe('Manejo del Título del Navegador', () => {
    it('debería actualizar el estado y llamar a Title.setTitle si el título no es null', () => {
      service.setDynamicTitle('Nuevo Título');
      expect(service.dynamicTitle()).toBe('Nuevo Título');
      expect(mockTitleService.setTitle).toHaveBeenCalledWith('Nuevo Título');
    });

    it('debería actualizar el estado pero NO llamar a Title.setTitle si es null', () => {
      service.setDynamicTitle(null);
      expect(service.dynamicTitle()).toBeNull();
      expect(mockTitleService.setTitle).not.toHaveBeenCalled();
    });
  });

  describe('Métodos de Fachada (setPageContext y clearPageContext)', () => {
    it('setPageContext debería actualizar el breadcrumb dinámico y el título', () => {
      service.setPageContext('Mi Breadcrumb', 'Mi Título');
      expect(service.breadcrumbs()[2]).toEqual({ label: 'Mi Breadcrumb', url: '/ruta-actual' });
      expect(service.dynamicTitle()).toBe('Mi Título');
      expect(mockTitleService.setTitle).toHaveBeenCalledWith('Mi Título');
    });

    it('clearPageContext debería limpiar tanto el breadcrumb como el título', () => {
      service.setPageContext('Mi Breadcrumb', 'Mi Título');
      service.clearPageContext();
      expect(service.breadcrumbs()).toHaveLength(2);
      expect(service.dynamicTitle()).toBeNull();
    });

    it('clearDynamicBreadcrumb debería remover solo el breadcrumb dinámico', () => {
      service.setDynamicBreadcrumb('Algo dinámico');
      service.clearDynamicBreadcrumb();
      expect(service.breadcrumbs()).toHaveLength(2);
    });
  });

  describe('Reactividad con Eventos del Router (toSignal)', () => {
    it('debería re-calcular los breadcrumbs cuando ocurre un NavigationEnd', () => {
      service.breadcrumbs();
      buildBreadcrumbTrailMock.mockReturnValue([
        { label: 'Ruta Nueva', url: '/ruta-nueva' }
      ]);
      const newSnapshot: RouterStateSnapshot = {
        root: createMockRouteSnapshot(),
        url: '/ruta-nueva'
      };
      mockRouter.routerState.snapshot = newSnapshot;
      routerEventsSubject.next(new NavigationEnd(1, '/nueva', '/nueva'));
      TestBed.flushEffects();
      expect(service.breadcrumbs()).toEqual([
        { label: 'Inicio', url: '/' },
        { label: 'Ruta Nueva', url: '/ruta-nueva' }
      ]);
      expect(buildBreadcrumbTrailMock).toHaveBeenCalledWith(newSnapshot.root);
    });

    it('NO debería re-calcular los breadcrumbs con otros eventos del router', () => {
      service.breadcrumbs();
      buildBreadcrumbTrailMock.mockClear();
      routerEventsSubject.next(new NavigationStart(1, '/test'));
      TestBed.flushEffects();
      service.breadcrumbs();
      expect(buildBreadcrumbTrailMock).not.toHaveBeenCalled();
    });
  });

  describe('Retrocompatibilidad (toObservable)', () => {
    it('debería emitir valores a través de dynamicTitle$ cuando el signal cambia', () => {
      const emittedTitles: (string | null)[] = [];
      const sub = service.dynamicTitle$.subscribe((title) => {
        emittedTitles.push(title);
      });
      TestBed.flushEffects();
      service.setDynamicTitle('Observable Test');
      TestBed.flushEffects();
      expect(emittedTitles).toEqual([null, 'Observable Test']);
      sub.unsubscribe();
    });

    it('debería emitir valores a través de breadcrumbs$ cuando los breadcrumbs cambian', () => {
      const emittedBreadcrumbs: BreadcrumbItem[][] = [];
      const sub = service.breadcrumbs$.subscribe((items) => {
        emittedBreadcrumbs.push(items);
      });
      TestBed.flushEffects();
      service.setDynamicBreadcrumb('Página Dinámica');
      TestBed.flushEffects();
      expect(emittedBreadcrumbs).toHaveLength(2);
      expect(emittedBreadcrumbs[1]).toContainEqual({
        label: 'Página Dinámica',
        url: '/ruta-actual'
      });
      sub.unsubscribe();
    });
  });
});

import { ComponentFixture, TestBed } from '@angular/core/testing';
import { Router } from '@angular/router';
import { signal, WritableSignal, Component, Input, Output, EventEmitter } from '@angular/core';
import { NotificationsPageComponent } from './notifications-page.component';
import { NotificationsPageFacadeService } from './services/notifications-page-facade.service';
import { InboxMessageTableRow, ModalActionType } from './../../models/notifications-page.model';
import { TableButton } from '../../../../shared/components/table-component/table-component.component';
import { NotificationType } from '../../../../shared/components/notifications/models/notification.model';
import { TableComponent } from '../../../../shared/components/table-component/table-component.component';
import { ConfirmationActionModalComponent } from '../../../../shared/components/modals/confirmation-action-modal/confirmation-action-modal.component';

const createMockInboxMessageTableRow = (overrides: Partial<InboxMessageTableRow> = {}): InboxMessageTableRow => ({
  id: 'row-default',
  userId: 'user-123',
  type: NotificationType.INFO,
  title: 'Título del mensaje',
  message: 'Cuerpo del mensaje',
  date: new Date(),
  status: 'no leido',
  stateLabel: 'No Leído',
  dateFormatted: 'Hace un momento',
  allowedActions: ['ver_detalle', 'eliminar'],
  ...overrides
} as InboxMessageTableRow);

@Component({ selector: 'app-table-component', standalone: true, template: '' })
class MockTableComponent {
  @Input() value!: unknown[];
  @Input() headerButtons!: unknown[];
  @Input() columns!: unknown[];
  @Input() paginator!: boolean;
  @Input() rows!: number;
  @Input() emptyMessage!: string;
  @Output() actionClick = new EventEmitter<{ action: string; row: InboxMessageTableRow }>();
  @Output() headerButtonClick = new EventEmitter<TableButton>();
}

@Component({ selector: 'app-confirmation-action-modal', standalone: true, template: '' })
class MockConfirmationActionModalComponent {
  @Input() isOpen!: boolean;
  @Input() description!: string;
  @Output() onClose = new EventEmitter<void>();
  @Output() confirm = new EventEmitter<void>();
}

describe('NotificationsPageComponent', () => {
  let component: NotificationsPageComponent;
  let fixture: ComponentFixture<NotificationsPageComponent>;
  let mockRouter: {
    navigateByUrl: jest.Mock<Promise<boolean>, [string]>;
  };
  let mockFacade: {
    tableData: WritableSignal<InboxMessageTableRow[]>;
    headerButtons: WritableSignal<TableButton[]>;
    markAsRead: jest.Mock<void, [string]>;
    clearAllMessages: jest.Mock<void, []>;
    deleteMessage: jest.Mock<void, [string]>;
  };
  beforeEach(async () => {
    jest.spyOn(console, 'error').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    mockRouter = {
      navigateByUrl: jest.fn().mockResolvedValue(true),
    };
    mockFacade = {
      tableData: signal<InboxMessageTableRow[]>([]),
      headerButtons: signal<TableButton[]>([]),
      markAsRead: jest.fn(),
      clearAllMessages: jest.fn(),
      deleteMessage: jest.fn(),
    };
    await TestBed.configureTestingModule({
      imports: [NotificationsPageComponent],
      providers: [
        { provide: Router, useValue: mockRouter },
        { provide: NotificationsPageFacadeService, useValue: mockFacade },
      ],
    })
    .overrideComponent(NotificationsPageComponent, {
      remove: { imports: [TableComponent, ConfirmationActionModalComponent] },
      add: { imports: [MockTableComponent, MockConfirmationActionModalComponent] }
    })
    .compileComponents();
    fixture = TestBed.createComponent(NotificationsPageComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });
  afterEach(() => {
    jest.clearAllMocks();
    jest.restoreAllMocks();
  });

  it('debería crear el componente correctamente', () => {
    expect(component).toBeTruthy();
  });

  describe('Estado Inicial', () => {
    it('debería iniciar con el modal cerrado y sin acciones pendientes', () => {
      expect(component.isConfirmModalOpen()).toBeFalsy();
      expect(component.pendingAction()).toBeNull();
      expect(component.pendingNotificationId()).toBeNull();
      expect(component.modalDescription()).toBe('');
    });
  });
  describe('Propiedad Computada: modalDescription', () => {
    it('debería retornar el mensaje correcto para "clear_all"', () => {
      component.pendingAction.set('clear_all');
      expect(component.modalDescription()).toContain('vaciar por completo su bandeja');
    });
    it('debería retornar el mensaje correcto para "delete_single"', () => {
      component.pendingAction.set('delete_single');
      expect(component.modalDescription()).toContain('eliminar esta notificación');
    });
    it('debería retornar un string vacío si la acción no coincide', () => {
      component.pendingAction.set(null);
      expect(component.modalDescription()).toBe('');
    });
  });
  describe('Interacciones de la Tabla (handleTableAction)', () => {
    const mockRow = createMockInboxMessageTableRow({
      id: 'notif-123',
      actionUrl: '/some/path',
    });
    it('debería marcar como leída y navegar si la acción es "ver_detalle"', () => {
      component.handleTableAction({ action: 'ver_detalle', row: mockRow });
      expect(mockFacade.markAsRead).toHaveBeenCalledWith('notif-123');
      expect(mockRouter.navigateByUrl).toHaveBeenCalledWith('/some/path');
    });
    it('no debería navegar si la acción es "ver_detalle" pero no hay actionUrl', () => {
      const rowWithoutUrl = createMockInboxMessageTableRow({
        id: 'notif-123',
        actionUrl: undefined
      });
      component.handleTableAction({ action: 'ver_detalle', row: rowWithoutUrl });
      expect(mockFacade.markAsRead).toHaveBeenCalledWith('notif-123');
      expect(mockRouter.navigateByUrl).not.toHaveBeenCalled();
    });
    it('debería abrir el modal y configurar acción al elegir "eliminar"', () => {
      component.handleTableAction({ action: 'eliminar', row: mockRow });
      expect(component.pendingAction()).toBe('delete_single');
      expect(component.pendingNotificationId()).toBe('notif-123');
      expect(component.isConfirmModalOpen()).toBeTruthy();
    });
  });
  describe('Interacciones del Header (handleHeaderButton & requestClearAll)', () => {
    it('debería solicitar limpiar bandeja al presionar el botón "Limpiar Bandeja"', () => {
      const btn: TableButton = { label: 'Limpiar Bandeja', action: 'clear', variant: 'primary' };
      component.handleHeaderButton(btn);
      expect(component.pendingAction()).toBe('clear_all');
      expect(component.isConfirmModalOpen()).toBeTruthy();
    });
    it('no debería hacer nada si el botón no es el esperado', () => {
      const btn: TableButton = { label: 'Otro Botón', action: 'other', variant: 'secondary' };
      component.handleHeaderButton(btn);
      expect(component.pendingAction()).toBeNull();
      expect(component.isConfirmModalOpen()).toBeFalsy();
    });
  });
  describe('Gestión del Modal (ejecución y cerrado)', () => {
    it('debería resetear los signals al cerrar el modal (closeModal)', () => {
      component.isConfirmModalOpen.set(true);
      component.pendingAction.set('clear_all');
      component.pendingNotificationId.set('123');
      component.closeModal();
      expect(component.isConfirmModalOpen()).toBeFalsy();
      expect(component.pendingAction()).toBeNull();
      expect(component.pendingNotificationId()).toBeNull();
    });
    it('debería ejecutar la limpieza total y cerrar el modal si la acción era "clear_all"', () => {
      jest.spyOn(component, 'closeModal');
      component.pendingAction.set('clear_all');
      component.executePendingAction();
      expect(mockFacade.clearAllMessages).toHaveBeenCalled();
      expect(component.closeModal).toHaveBeenCalled();
    });
    it('debería ejecutar borrado individual y cerrar el modal si la acción era "delete_single"', () => {
      jest.spyOn(component, 'closeModal');
      component.pendingAction.set('delete_single');
      component.pendingNotificationId.set('notif-456');
      component.executePendingAction();
      expect(mockFacade.deleteMessage).toHaveBeenCalledWith('notif-456');
      expect(component.closeModal).toHaveBeenCalled();
    });
    it('no debería ejecutar borrado individual si no hay pendingNotificationId', () => {
      jest.spyOn(component, 'closeModal');
      component.pendingAction.set('delete_single');
      component.pendingNotificationId.set(null);
      component.executePendingAction();
      expect(mockFacade.deleteMessage).not.toHaveBeenCalled();
      expect(component.closeModal).toHaveBeenCalled();
    });
  });
});

import { TestBed } from '@angular/core/testing';
import { signal, WritableSignal } from '@angular/core';
import { NotificationsPageFacadeService } from './notifications-page-facade.service';
import { InboxService } from '../../../services/inbox.service';
import { NotificationsPageMapperService } from './notifications-page-mapper.service';
import { InboxMessage, InboxStatus } from '../../../interfaces/inbox-message.interface';
import { InboxMessageTableRow } from '../../../models/notifications-page.model';
import { NotificationType } from '../../../../../shared/components/notifications/models/notification.model';

const createMockInboxMessage = (overrides: Partial<InboxMessage> = {}): InboxMessage => ({
  id: 'msg-default',
  userId: 'user-123',
  type: NotificationType.INFO,
  title: 'Título del mensaje',
  message: 'Cuerpo del mensaje',
  date: new Date(),
  status: 'no leido',
  ...overrides
} as InboxMessage);

const createMockInboxMessageTableRow = (overrides: Partial<InboxMessageTableRow> = {}): InboxMessageTableRow => ({
  id: 'row-default',
  title: 'Título del mensaje',
  date: new Date(),
  isRead: false,
  ...overrides
} as InboxMessageTableRow);

describe('NotificationsPageFacadeService', () => {
  let facadeService: NotificationsPageFacadeService;
  let mockMessagesSignal: WritableSignal<InboxMessage[]>;
  let mockInboxService: {
    messages: WritableSignal<InboxMessage[]>;
    markAsRead: jest.Mock<void, [string]>;
    deleteMessage: jest.Mock<void, [string]>;
    clearAllMessages: jest.Mock<void, []>;
  };
  let mockMapperService: {
    mapMessageToRow: jest.Mock<InboxMessageTableRow, [InboxMessage]>;
  };
  beforeEach(() => {
    jest.spyOn(console, 'error').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    mockMessagesSignal = signal<InboxMessage[]>([]);
    mockInboxService = {
      messages: mockMessagesSignal,
      markAsRead: jest.fn(),
      deleteMessage: jest.fn(),
      clearAllMessages: jest.fn(),
    };
    mockMapperService = {
      mapMessageToRow: jest.fn((msg: InboxMessage) => createMockInboxMessageTableRow({
        id: msg.id,
        title: msg.title,
        date: msg.date
      })),
    };
    TestBed.configureTestingModule({
      providers: [
        NotificationsPageFacadeService,
        { provide: InboxService, useValue: mockInboxService },
        { provide: NotificationsPageMapperService, useValue: mockMapperService },
      ],
    });
    facadeService = TestBed.inject(NotificationsPageFacadeService);
  });
  afterEach(() => {
    jest.clearAllMocks();
    jest.restoreAllMocks();
  });
  describe('Propiedades Computadas para la UI (tableData y headerButtons)', () => {
    it('debe retornar tabla vacía y sin botones si no hay mensajes', () => {
      mockMessagesSignal.set([]);
      expect(facadeService.tableData()).toEqual([]);
      expect(facadeService.headerButtons()).toEqual([]);
      expect(mockMapperService.mapMessageToRow).not.toHaveBeenCalled();
    });
    it('debe mapear los mensajes a filas de tabla usando el MapperService', () => {
      const mockMessages: InboxMessage[] = [
        createMockInboxMessage({ id: '1', title: 'Mensaje 1' }),
        createMockInboxMessage({ id: '2', title: 'Mensaje 2' }),
      ];
      mockMessagesSignal.set(mockMessages);
      const rows = facadeService.tableData();
      expect(rows).toHaveLength(2);
      expect(rows[0].id).toBe('1');
      expect(rows[1].id).toBe('2');
      expect(mockMapperService.mapMessageToRow).toHaveBeenCalledTimes(2);
      expect(mockMapperService.mapMessageToRow).toHaveBeenCalledWith(mockMessages[0]);
      expect(mockMapperService.mapMessageToRow).toHaveBeenCalledWith(mockMessages[1]);
    });
    it('debe mostrar el botón "Limpiar Bandeja" cuando existen filas en la tabla', () => {
      mockMessagesSignal.set([
        createMockInboxMessage({ id: '1', title: 'Mensaje 1' })
      ]);
      const buttons = facadeService.headerButtons();
      expect(buttons).toHaveLength(1);
      expect(buttons[0]).toEqual({ label: 'Limpiar Bandeja', variant: 'primary' });
    });
    it('debe reaccionar dinámicamente: quitar el botón si la tabla se vacía', () => {
      mockMessagesSignal.set([
        createMockInboxMessage({ id: '1', title: 'Mensaje 1' })
      ]);
      expect(facadeService.headerButtons()).toHaveLength(1);
      mockMessagesSignal.set([]);
      expect(facadeService.tableData()).toHaveLength(0);
      expect(facadeService.headerButtons()).toHaveLength(0);
    });
  });
  describe('Delegación de Acciones al InboxService', () => {
    it('debe delegar markAsRead correctamente', () => {
      facadeService.markAsRead('msg-123');
      expect(mockInboxService.markAsRead).toHaveBeenCalledWith('msg-123');
    });
    it('debe delegar deleteMessage correctamente', () => {
      facadeService.deleteMessage('msg-456');
      expect(mockInboxService.deleteMessage).toHaveBeenCalledWith('msg-456');
    });
    it('debe delegar clearAllMessages correctamente', () => {
