    it('documentUploadDate debería formatear correctamente la fecha del primer documento', () => {
      const uploadDateStr = facade.documentUploadDate();
      expect(uploadDateStr).toMatch(/23.*7.*2026|23\/7\/2026|23\/07\/2026/);
    });
