}

describe('ProposalPageComponent', () => {
  let component: ProposalPageComponent;
  let fixture: ComponentFixture<ProposalPageComponent>;
  let mockRouter: { navigate: jest.Mock };
  let mockFacade: {
    proposalsTableData: ReturnType<typeof signal<ProposalTableRow[]>>;
    headerButtons: ReturnType<typeof signal<TableButton[]>>;
    showRestrictedAccessNotification: jest.Mock;
    annulProposal: jest.Mock;
  };

  const mockRow: ProposalTableRow = {
    id: 'prop-1',
    title: 'Test',
    description: 'Desc test',
    allowedActions: ['ver', 'ver descripcion', 'editar', 'anular']
  } as ProposalTableRow;

  beforeEach(async () => {
    jest.spyOn(console, 'log').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    jest.spyOn(console, 'error').mockImplementation(() => {});

    mockRouter = { navigate: jest.fn() };
    mockFacade = {
      proposalsTableData: signal([mockRow]),
      headerButtons: signal([]),
      showRestrictedAccessNotification: jest.fn(),
      annulProposal: jest.fn()
    };

    await TestBed.configureTestingModule({
      imports: [ProposalPageComponent],
      providers: [
        { provide: Router, useValue: mockRouter },
        { provide: ProposalFacadeService, useValue: mockFacade }
      ]
    })
    .overrideComponent(ProposalPageComponent, {
      remove: { imports: [TableComponent, DescriptionModalComponent, ConfirmationActionModalComponent] },
      add: { imports: [MockTableComponent, MockDescriptionModalComponent, MockConfirmationActionModalComponent] }
    })
    .compileComponents();

    fixture = TestBed.createComponent(ProposalPageComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('handleTableAction', () => {
    it('debe notificar si la acción no está permitida', () => {
      const restrictedRow = { ...mockRow, allowedActions: ['ver'] };

      component.handleTableAction({ action: 'editar', row: restrictedRow });

      expect(mockFacade.showRestrictedAccessNotification).toHaveBeenCalled();
      expect(mockRouter.navigate).not.toHaveBeenCalled();
    });

    it('debe abrir modal de descripción al accionar "ver descripcion"', () => {
      component.handleTableAction({ action: 'ver descripcion', row: mockRow });

      expect(component.descriptionModal.show).toBeTruthy();
      expect(component.descriptionModal.content).toBe('Desc test');
    });

    it('debe navegar al detalle al accionar "ver"', () => {
      component.handleTableAction({ action: 'ver', row: mockRow });
      expect(mockRouter.navigate).toHaveBeenCalledWith(['/proposal/details', 'prop-1']);
    });

    it('debe abrir el modal de anulación al accionar "anular"', () => {
      component.handleTableAction({ action: 'anular', row: mockRow });
      expect(component.annulState.show).toBeTruthy();
      expect(component.annulState.id).toBe('prop-1');
    });
  });

  describe('handleHeaderButton', () => {
    it('debe navegar a crear propuesta', () => {
      component.handleHeaderButton({ label: 'Registrar propuesta', icon: '', action: '', variant: 'primary' });
      expect(mockRouter.navigate).toHaveBeenCalledWith(['/proposal/create']);
    });
  });

  describe('confirmAnnul', () => {
    it('debe llamar a annulProposal en fachada y resetear modal en éxito', () => {
      component.annulState = { show: true, id: 'prop-1', title: 'Test', loading: false };

      component.confirmAnnul('Motivo');
      expect(component.annulState.loading).toBeTruthy();

      const onSuccess = mockFacade.annulProposal.mock.calls[0][2];
      onSuccess();

      expect(component.annulState.show).toBeFalsy();
      expect(component.annulState.id).toBeNull();
    });
  });
});

import { TestBed } from '@angular/core/testing';
import { of, throwError } from 'rxjs';
import { ProposalFacadeService } from './proposal-facade.service';
import { ProposalService } from '../../../services/proposal.service';
import { AuthService } from '../../../../../core/services/auth/auth.service';
import { NotificationService } from '../../../../../shared/components/notifications/services/notification.service';
import { ProposalMapperService } from './proposal-mapper.service';
import { signal } from '@angular/core';
import { NotificationType } from '../../../../../shared/components/notifications/models/notification.model';
import { Proposal } from '../../../interfaces/proposal.interface';
import { ProposalTableRow } from '../models/proposal-page.model';
import { TrabajoGradoStoreService } from '../../../../../core/services/trabajo-grado/trabajo-grado-store.service';
import { crearTrabajoDePrueba, crearTrabajoEnCurso } from '../../../../../testing/trabajo-grado-de-prueba';
import { UserRoleType } from '../../../../../core/enums/user-role-type.enum';

describe('ProposalFacadeService', () => {
  let service: ProposalFacadeService;
  const trabajosDelStore = signal([crearTrabajoDePrueba({ id: 1 }), crearTrabajoEnCurso({ id: 2 })]);

  let mockProposalService: { proposals: any; annulProposal: jest.Mock };
  let mockAuthService: { currentUser: any; hasAnyRole: jest.Mock };
  let mockNotificationService: { show: jest.Mock };
  let mockMapperService: { mapProposalToTable: jest.Mock };

  beforeEach(() => {
    jest.spyOn(console, 'log').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    jest.spyOn(console, 'error').mockImplementation(() => {});

    mockProposalService = {
      proposals: signal([{ id: 'prop-1' } as Proposal]),
      annulProposal: jest.fn()
    };

    mockAuthService = {
      currentUser: signal({ id: 'user-1' }),
      hasAnyRole: jest.fn()
    };

    mockNotificationService = { show: jest.fn() };

    mockMapperService = {
      mapProposalToTable: jest.fn().mockReturnValue({ id: 'prop-1', title: 'Mapped' } as ProposalTableRow)
    };

    TestBed.configureTestingModule({
      providers: [
        ProposalFacadeService,
        { provide: ProposalService, useValue: mockProposalService },
        { provide: AuthService, useValue: mockAuthService },
        { provide: NotificationService, useValue: mockNotificationService },
        { provide: ProposalMapperService, useValue: mockMapperService },
        { provide: TrabajoGradoStoreService, useValue: { trabajos: trabajosDelStore } }
      ]
    });

    service = TestBed.inject(ProposalFacadeService);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('Propiedades Computed', () => {
    it('proposalsTableData debe retornar datos mapeados reactivamente', () => {
      mockAuthService.hasAnyRole.mockReturnValue(true); // isAdmin

      const tableData = service.proposalsTableData();

      expect(tableData).toHaveLength(1);
      expect(tableData[0].title).toBe('Mapped');
      expect(mockMapperService.mapProposalToTable).toHaveBeenCalled();
    });

    it('la anulación depende de la etapa del trabajo en el backend', () => {
      mockProposalService.proposals.set([{ id: '1' } as Proposal, { id: '2' } as Proposal]);
      service.proposalsTableData();
      expect(mockMapperService.mapProposalToTable.mock.calls.map(llamada => llamada[2])).toEqual([true, false]);
    });

    it('headerButtons debe incluir "Registrar propuesta" si tiene rol', () => {
      mockAuthService.hasAnyRole.mockImplementation((roles: UserRoleType[]) => !roles.includes(UserRoleType.JEFE_DEP));

      const buttons = service.headerButtons();
      expect(buttons.some(button => button.label === 'Registrar propuesta')).toBeTruthy();
    });

    it('el jefe de departamento no registra propuestas (no dirige trabajos de grado)', () => {
      mockAuthService.hasAnyRole.mockReturnValue(true);
      expect(service.headerButtons().some(button => button.label === 'Registrar propuesta')).toBeFalsy();
    });

    it('headerButtons NO debe incluir "Registrar propuesta" si no tiene permisos', () => {
      mockAuthService.hasAnyRole.mockReturnValue(false);

      const buttons = service.headerButtons();
      expect(buttons.some(button => button.label === 'Registrar propuesta')).toBeFalsy();
    });
  });

  describe('annulProposal', () => {
    it('anula con la justificación y avisa que quedó en el historial', () => {
      mockProposalService.annulProposal.mockReturnValue(of({}));
      const onSuccess = jest.fn();

      service.annulProposal('1', 'Motivo', onSuccess, jest.fn());

      expect(mockProposalService.annulProposal).toHaveBeenCalledWith('1', 'Motivo');
      expect(mockNotificationService.show).toHaveBeenCalledWith(expect.objectContaining({
        type: NotificationType.CONFIRMATION, title: 'Propuesta anulada' }));
      expect(onSuccess).toHaveBeenCalled();
    });

    it('debe manejar el flujo de error y notificar', () => {
      mockProposalService.annulProposal.mockReturnValue(throwError(() => new Error('Simulated Error')));
      const onError = jest.fn();

      service.annulProposal('1', 'Motivo', jest.fn(), onError);

      expect(mockNotificationService.show).toHaveBeenCalledWith(expect.objectContaining({ type: NotificationType.ERROR }));
      expect(onError).toHaveBeenCalled();
    });
  });

  describe('showRestrictedAccessNotification', () => {
    it('debe mostrar notificación de error por acceso restringido', () => {
      service.showRestrictedAccessNotification();
      expect(mockNotificationService.show).toHaveBeenCalledWith(
        expect.objectContaining({ type: NotificationType.ERROR, title: 'Acceso restringido' })
      );
    });
  });
});

import { TestBed } from '@angular/core/testing';
import { of } from 'rxjs';
import { ProposalRulesService, propuestaEditable } from './proposal-rules.service';
import { ProposalStorageService } from './proposal-storage.service';
import { UserService } from '../../users/services/user.service';
import { Proposal } from '../interfaces/proposal.interface';
import { stateList } from '../../../core/enums/state.enum';
import { FileDocument } from '../../../core/interfaces/file-document.interface';

describe('ProposalRulesService', () => {
  let service: ProposalRulesService;
  let mockStorageService: Partial<ProposalStorageService>;
  let mockUserService: Partial<UserService>;
  beforeEach(() => {
    jest.spyOn(console, 'log').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    jest.spyOn(console, 'error').mockImplementation(() => {});
    mockStorageService = {
      getProposalsListSnapshot: jest.fn().mockReturnValue([])
    };
    mockUserService = {
      getUserFullName: jest.fn().mockReturnValue('Juan Perez')
    };
    TestBed.configureTestingModule({
      providers: [
        ProposalRulesService,
        { provide: ProposalStorageService, useValue: mockStorageService as ProposalStorageService },
        { provide: UserService, useValue: mockUserService as UserService }
      ]
    });
    service = TestBed.inject(ProposalRulesService);
  });
  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('validateProposalRules', () => {
    it('debería fallar si el director y codirector son la misma persona', () => {
      const invalidProposal: Partial<Proposal> = {
        director: { id: 'doc-1' } as any,
        codirector: { id: 'doc-1' } as any
      };
      const result = service.validateProposalRules(invalidProposal);
      expect(result).toBe('Un docente no puede ser Director y Codirector simultáneamente.');
    });
    it('debería fallar si un estudiante ya tiene 2 o más propuestas registradas', () => {
      const newProposal: Partial<Proposal> = {
        id: 'prop-3',
        authors: [{ id: 'stu-1' } as any]
      };
      (mockStorageService.getProposalsListSnapshot as jest.Mock).mockReturnValue([
        { id: 'prop-1', authors: [{ id: 'stu-1' }] },
        { id: 'prop-2', authors: [{ id: 'stu-1' }] }
      ] as Proposal[]);
      const result = service.validateProposalRules(newProposal);
      expect(result).toBe('El estudiante Juan Perez ya tiene 2 propuestas registradas (límite máximo institucional).');
      expect(mockUserService.getUserFullName).toHaveBeenCalledWith('stu-1');
    });
    it('debería retornar null si la propuesta cumple todas las reglas', () => {
      const validProposal: Partial<Proposal> = {
        id: 'prop-nuevo',
        director: { id: 'doc-1' } as any,
        codirector: { id: 'doc-2' } as any,
        authors: [{ id: 'stu-1' } as any]
      };
      (mockStorageService.getProposalsListSnapshot as jest.Mock).mockReturnValue([
        { id: 'prop-1', authors: [{ id: 'stu-1' }] }
      ] as Proposal[]);
      const result = service.validateProposalRules(validProposal);
      expect(result).toBeNull();
    });
  });
});

describe('propuestaEditable', () => {
  const documento = { id: 'd1' } as FileDocument;

  it('permite corregir antes de radicar el formato A', () => {
    expect(propuestaEditable({ state: stateList.EN_REVISION, documents: [] })).toBe(true);
  });
  it('permite corregir después de un concepto no pertinente del Comité', () => {
    expect(propuestaEditable({ state: stateList.NO_PERTINENTE, documents: [documento] })).toBe(true);
  });
  it.each([stateList.EN_REVISION, stateList.PERTINENTE])('no permite corregir una propuesta radicada en estado %s', estado => {
    expect(propuestaEditable({ state: estado, documents: [documento] })).toBe(false);
  });
});

import { Component, EventEmitter, Input, OnChanges, Output, SimpleChanges } from '@angular/core';
import { DialogModule } from 'primeng/dialog';
import { ButtonComponent } from '../../../../shared/components/button-component/button-component.component';
import { StatisticsReportFormat } from '../../services/statistics-reports.service';

/** Formato que se puede elegir, con su botón y lo que trae el archivo */
interface ReportFormatOption {
  format: StatisticsReportFormat;
  label: string;
  icon: string;
  description: string;
}

export const REPORT_FORMAT_OPTIONS: readonly ReportFormatOption[] = [
  { format: 'pdf', label: 'PDF', icon: 'picture_as_pdf',
    description: 'Para imprimir o compartir: alcance, filtros, métricas y la tabla de trabajos.' },
  { format: 'excel', label: 'Excel', icon: 'table_view',
    description: 'Para analizar los datos: hoja "Trabajos" con la tabla y hoja "Resumen" con los filtros y las métricas.' },
  { format: 'csv', label: 'CSV', icon: 'description',
    description: 'Para llevar los datos a otra herramienta: solo la tabla de trabajos, separada por punto y coma.' }
];

/**
 * Confirmación del reporte de estadísticas: muestra cuántos trabajos lleva y
 * deja elegir el formato en que se descarga.
 */
@Component({
  selector: 'app-report-format-modal',
  imports: [DialogModule, ButtonComponent],
  templateUrl: './report-format-modal.component.html'
})
export class ReportFormatModalComponent implements OnChanges {

  @Input() isOpen = false;
  /** Trabajos que lleva el reporte (los que dejan los filtros) */
  @Input() rows = 0;

  @Output() onClose = new EventEmitter<void>();
  @Output() selectFormat = new EventEmitter<StatisticsReportFormat>();

  readonly options = REPORT_FORMAT_OPTIONS;

  /** Ya se eligió un formato en esta apertura: un doble clic no descarga dos veces */
  selected = false;

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['isOpen']?.currentValue) this.selected = false;
  }

  get description(): string {
    if (this.rows === 0) return 'Con los filtros actuales no hay trabajos: el reporte saldrá sin filas.';
    return `Se generará el reporte con ${this.rows === 1 ? 'el trabajo' : `los ${this.rows} trabajos`} que dejan los filtros actuales. Elige el formato en que quieres descargarlo:`;
  }

  closeModal(): void {
    this.onClose.emit();
  }

  choose(format: StatisticsReportFormat): void {
    if (this.selected) return;
    this.selected = true;
    this.selectFormat.emit(format);
    this.closeModal();
  }
}

import { TestBed } from '@angular/core/testing';
import { signal, WritableSignal } from '@angular/core';
import { StatisticsPageFacadeService } from './statistics-page-facade.service';
import { StatisticsStateService } from '../../../services/statistics-state.service';
import { StatisticsMetricsService } from '../../../services/statistics-metrics.service';
import { StatisticsChartDataService } from '../../../services/statistics-chart-data.service';
import { StatisticsReportContext, StatisticsReportService } from '../../../services/statistics-reports.service';
import { DEFAULT_STATISTICS_FILTERS, StatisticsFilters } from '../../../interfaces/statisticsFilters.interface';
import { StatisticsReportKpis } from '../../../interfaces/statisticsReportKpis.interface';
import { RawProjectData } from '../../../interfaces/rawProjectData.interface';
import { ProjectStage } from '../../../enum/projectStage.enum';

interface MockChartData {
  labels: string[];
  datasets: Record<string, unknown>[];
}

interface MockStageOption {
  label: string;
  value: ProjectStage | null;
}

const createMockRawProjectData = (overrides: Partial<RawProjectData> = {}): RawProjectData => ({
  id: 'proj-123',
  title: 'Proyecto Mock',
  stage: ProjectStage.PROPUESTA,
  status: 'EN_DESARROLLO' as any,
  originalState: 'EN_REVISION',
  period: '2026-1',
  directorId: 'usr-1',
  directorName: 'Director Mock',
  registrationDate: new Date(),
  isArchived: false,
  deadlineStatus: null,
  ...overrides
} as RawProjectData);

describe('StatisticsPageFacadeService', () => {
  let facadeService: StatisticsPageFacadeService;
  let mockStateService: {
    currentFilters: WritableSignal<StatisticsFilters>;
    filteredData: WritableSignal<RawProjectData[]>;
    stagesOptions: MockStageOption[];
    periodsOptions: WritableSignal<string[]>;
    directorsOptions: WritableSignal<{ id: string; name: string }[]>;
    modalityOptions: WritableSignal<string[]>;
    programOptions: WritableSignal<string[]>;
    scope: WritableSignal<string>;
    updateFilters: jest.Mock<void, [Partial<StatisticsFilters>]>;
    clearFilters: jest.Mock<void, []>;
  };
  let mockMetricsService: {
    totalLoaded: WritableSignal<number>;
    totalApproved: WritableSignal<number>;
    totalInProgress: WritableSignal<number>;
    totalNotApproved: WritableSignal<number>;
  };
  let mockChartDataService: {
    statusChartData: WritableSignal<MockChartData>;
    stageChartData: WritableSignal<MockChartData>;
    modalityChartData: WritableSignal<MockChartData>;
    programChartData: WritableSignal<MockChartData>;
  };
  let mockReportService: {
    downloadPdfReport: jest.Mock<void, [StatisticsFilters, RawProjectData[], StatisticsReportKpis, StatisticsReportContext]>;
    downloadExcelReport: jest.Mock<Promise<void>, [StatisticsFilters, RawProjectData[], StatisticsReportKpis, StatisticsReportContext]>;
    downloadCsvReport: jest.Mock<void, [StatisticsFilters, RawProjectData[], StatisticsReportKpis, StatisticsReportContext]>;
  };
  beforeEach(() => {
    jest.spyOn(console, 'error').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    mockStateService = {
      currentFilters: signal<StatisticsFilters>({ ...DEFAULT_STATISTICS_FILTERS }),
      filteredData: signal<RawProjectData[]>([]),
      stagesOptions: [],
      periodsOptions: signal<string[]>(['2026-1', '2025-2']),
      directorsOptions: signal<{ id: string; name: string }[]>([{ id: 'd1', name: 'Director 1' }]),
      modalityOptions: signal<string[]>([]),
      programOptions: signal<string[]>([]),
      scope: signal('Todos los trabajos de grado de la facultad.'),
      updateFilters: jest.fn(),
      clearFilters: jest.fn(),
    };
    mockMetricsService = {
      totalLoaded: signal<number>(10),
      totalApproved: signal<number>(5),
      totalInProgress: signal<number>(3),
      totalNotApproved: signal<number>(2),
    };
    mockChartDataService = {
      statusChartData: signal<MockChartData>({ labels: [], datasets: [] }),
      stageChartData: signal<MockChartData>({ labels: [], datasets: [] }),
      modalityChartData: signal<MockChartData>({ labels: [], datasets: [] }),
      programChartData: signal<MockChartData>({ labels: [], datasets: [] }),
    };
    mockReportService = {
      downloadPdfReport: jest.fn(),
      downloadExcelReport: jest.fn(() => Promise.resolve()),
      downloadCsvReport: jest.fn(),
    };
    TestBed.configureTestingModule({
      providers: [
        StatisticsPageFacadeService,
        { provide: StatisticsStateService, useValue: mockStateService },
        { provide: StatisticsMetricsService, useValue: mockMetricsService },
        { provide: StatisticsChartDataService, useValue: mockChartDataService },
        { provide: StatisticsReportService, useValue: mockReportService },
      ],
    });
    facadeService = TestBed.inject(StatisticsPageFacadeService);
  });
  afterEach(() => {
    jest.clearAllMocks();
    jest.restoreAllMocks();
  });
  describe('Exposición de Estado y Signals (Propiedades de Lectura)', () => {
    it('debería re-exponer correctamente las opciones y filtros del StateService', () => {
      expect(facadeService.currentFilters()).toEqual(mockStateService.currentFilters());
      expect(facadeService.stagesOptions).toEqual(mockStateService.stagesOptions);
      expect(facadeService.periodsOptions()).toEqual(['2026-1', '2025-2']);
      expect(facadeService.directorsOptions()).toEqual([{ id: 'd1', name: 'Director 1' }]);
    });
    it('debería re-exponer correctamente los KPIs del MetricsService', () => {
      expect(facadeService.totalLoaded()).toBe(10);
      expect(facadeService.totalApproved()).toBe(5);
      expect(facadeService.totalInProgress()).toBe(3);
      expect(facadeService.totalNotApproved()).toBe(2);
    });
    it('debería re-exponer correctamente los datos de gráficos del ChartDataService', () => {
      expect(facadeService.statusChartData()).toEqual({ labels: [], datasets: [] });
      expect(facadeService.stageChartData()).toEqual({ labels: [], datasets: [] });
