        expect(titleSpy.setTitle).toHaveBeenCalledWith('Trabajo de Grado - Versión definitiva');
        done();
      }, 10);
    });

    it('debe usar un valor por defecto para breadcrumb y title si la pestaña no se encuentra en la configuración', (done) => {
